/*菜单背景 */
.drawer-content {
    background-image: url('无');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

/*气泡本体 */
.mes {
  background: none;
  background-image: url('https://i.postimg.cc/hGZ0jSnK/IMG-3076.png');
  background-position: center center;
  background-repeat: repeat-y;
  background-size: 100%;
  background-attachment: scroll;
  box-shadow: 0 0 0px rgba(238, 151, 169, 0.8);


/*间距*/
--vertical-spacing: 8rem; 
     margin: var(--vertical-spacing) auto !important;
  --bubble-width: 100%;
}

/* ai文本 */
.mes[is_user="false"] .mes_text {
    padding: 10px 0px 0px 0px !important;
    letter-spacing: -0.3px;
}
/* 用户文本 */
.mes[is_user="true"] .mes_text {
    padding: 20px 0px 0px 0px !important; 
    letter-spacing: -0.3px;
}
.mes_text {
    line-height: 1.9; 
margin-left: -5px !important;
font-weight: 500!important;
}

/* 最后一条消息距离 源@小楼昨夜又东风老师 */
@media screen and (max-width: 1000px) {
    #chat .last_mes.mes {
        margin-bottom: 50px !important; 
    }
}

/*底层图片🫐 */
.mes::after {
  content: "";
  display: inline-block;
  background-image: url('https://i.postimg.cc/8cWhH1BG/IMG-3109.png');
   background-size: contain;
  background-repeat: no-repeat;
  background-position: center center; 

  width: 358px; /*宽度🫐没反应的话先调高 高度，再动宽度 */
  height: 50px; /*高度🫐 */

  /* 调整位置*/
  position: absolute;
  bottom: -44px; /*上下🫐 */
  left: 50%; /*左右🫐 */
  transform: translateX(-50%); /* 水平居中修正 */
}

/*顶层贴图🫐 */
.mes::before {
  content: "";
  display: inline-block;
  background-image: url('https://i.postimg.cc/XqhwKryR/IMG-3108.png');
  background-size: contain; 
  background-repeat: no-repeat;
  background-position: center center; 

  /* 调整大小 */
  width: 358px; /*宽度🫐没反应的话先调高 高度，再动宽度 */
  height: 190px; /*高度🫐 */

  /* 调整位置 */
  position: absolute;
  top: -184px; /*上下🫐 */
  left: 50%; /*左右🫐 */
  transform: translateX(-50%); /* 水平居中修正 */
}

.swipes-counter {
  position: absolute;
  top: 14px;
  right: 3px;
  z-index: 999;
  pointer-events: none;
